  "inlineSchema": "// HydroLink - Prisma schema (PostgreSQL)\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------- ENUMS ----------\n\nenum OtpPurpose {\n  REGISTER\n  RESET\n}\n\nenum PaymentMethod {\n  TELEBIRR\n  CBE\n  AWASH\n  CASH\n  OTHER\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n}\n\nenum BillStatus {\n  UNPAID\n  PAID\n  OVERDUE\n  PARTIAL\n}\n\nenum RequestType {\n  LEAK\n  NO_SUPPLY\n  LOW_PRESSURE\n  METER_ISSUE\n  BILLING_ISSUE\n  OTHER\n}\n\nenum RequestStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  REJECTED\n}\n\nenum Urgency {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum SupplyStatus {\n  AVAILABLE\n  SCHEDULED_OFF\n  UNSCHEDULED_OFF\n  LOW_PRESSURE\n}\n\nenum NotificationType {\n  BILL\n  PAYMENT\n  ANNOUNCEMENT\n  SCHEDULE\n  REQUEST\n  SYSTEM\n}\n\nenum DevicePlatform {\n  IOS\n  ANDROID\n}\n\n// ---------- MODELS ----------\n\nmodel User {\n  id            String   @id @default(uuid())\n  fullName      String\n  email         String   @unique\n  phone         String   @unique\n  passwordHash  String\n  accountNumber String   @unique\n  kebele        String?\n  isVerified    Boolean  @default(false)\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  otps            Otp[]\n  bills           Bill[]\n  payments        Payment[]\n  usageRecords    UsageRecord[]\n  serviceRequests ServiceRequest[]\n  notifications   Notification[]\n  deviceTokens    DeviceToken[]\n  refreshTokens   RefreshToken[]\n\n  @@index([kebele])\n}\n\nmodel RefreshToken {\n  id        String   @id @default(uuid())\n  token     String   @unique\n  userId    String\n  expiresAt DateTime\n  revoked   Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel Otp {\n  id        String     @id @default(uuid())\n  userId    String?\n  email     String\n  code      String\n  purpose   OtpPurpose\n  consumed  Boolean    @default(false)\n  expiresAt DateTime\n  createdAt DateTime   @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([email, purpose])\n}\n\nmodel Bill {\n  id          String     @id @default(uuid())\n  userId      String\n  periodMonth Int\n  periodYear  Int\n  usageM3     Float\n  amountEtb   Decimal\n  dueDate     DateTime\n  status      BillStatus @default(UNPAID)\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  payments Payment[]\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel Payment {\n  id             String        @id @default(uuid())\n  userId         String\n  billId         String\n  amountEtb      Decimal\n  method         PaymentMethod\n  status         PaymentStatus @default(PENDING)\n  transactionRef String?       @unique\n  paidAt         DateTime?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  bill Bill @relation(fields: [billId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([billId])\n}\n\nmodel Schedule {\n  id        String       @id @default(uuid())\n  kebele    String\n  dayOfWeek Int // 0=Sunday ... 6=Saturday\n  startTime String // \"06:00\"\n  endTime   String // \"10:00\"\n  status    SupplyStatus @default(SCHEDULED_OFF)\n  note      String?\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  @@index([kebele])\n  @@index([kebele, dayOfWeek])\n}\n\nmodel UsageRecord {\n  id          String   @id @default(uuid())\n  userId      String\n  periodMonth Int\n  periodYear  Int\n  usageM3     Float\n  createdAt   DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, periodMonth, periodYear])\n  @@index([userId])\n}\n\nmodel ServiceRequest {\n  id          String        @id @default(uuid())\n  userId      String\n  type        RequestType\n  description String\n  location    String?\n  urgency     Urgency       @default(MEDIUM)\n  status      RequestStatus @default(OPEN)\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel Announcement {\n  id        String   @id @default(uuid())\n  title     String\n  body      String\n  kebele    String? // null = all kebeles\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([kebele])\n}\n\nmodel Notification {\n  id        String           @id @default(uuid())\n  userId    String\n  type      NotificationType\n  title     String\n  body      String\n  isRead    Boolean          @default(false)\n  createdAt DateTime         @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([userId, isRead])\n}\n\nmodel DeviceToken {\n  id        String         @id @default(uuid())\n  userId    String\n  token     String         @unique\n  platform  DevicePlatform\n  createdAt DateTime       @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n",
